  clipPlane: vec4<f32>, clipConfig: vec4<f32>, clipMeta: vec4<f32>,
  inverseViewProj: mat4x4<f32>, position: vec4<f32>, clipCapColor: vec4<f32>,
  ambientIntensity: f32, clipBoxMin: vec3<f32>, clipBoxMax: vec3<f32>,
  clipSlabPlane: vec4<f32>, clipSlabWidths: vec4<f32>
