  var out: VertexOutput;
  let viewport = max(timeData.time.zw, vec2<f32>(1.0, 1.0));
  let ndcX = (input.position.x / viewport.x) * 2.0 - 1.0;
  let ndcY = 1.0 - (input.position.y / viewport.y) * 2.0;
  out.position = vec4<f32>(ndcX, ndcY, 0.0, 1.0);
  out.color = input.color;
  out.uv = input.uv;
